/**
 * Workbench Host artifact manifest: stable build artifact identity and integrity
 * metadata. Generated by `build.host.mjs` after esbuild, consumed by the
 * launch descriptor and supervisor to validate the build before spawning.
 *
 * The manifest is a JSON file written alongside the build output. Every output
 * entry carries a SHA-256 hash so the supervisor can verify the on-disk bytes
 * match the build-time artifact before launching.
 */

import { createHash, randomUUID } from 'node:crypto';
import { readFileSync, statSync } from 'node:fs';
import { isAbsolute, relative, resolve, sep } from 'node:path';
import { arch, platform } from 'node:os';

import { HOST_PROTOCOL_VERSION_V1 } from '@novalistically/workbench-protocol';

// ─── Types ─────────────────────────────────────────────────────────────────

export interface ArtifactManifestEntryV1 {
  /** Relative path from the build output root (e.g. `host/host/main.js`). */
  readonly path: string;
  /** SHA-256 hex digest of the file content. */
  readonly hash: string;
  /** File size in bytes. */
  readonly size: number;
  /**
   * When present, this entry is the canonical bundle for the named entry
   * point. Values match the `entryPoints` keys in `build.host.mjs`.
   */
  readonly entryPointFor?: string;
}

export interface ArtifactManifestBuildIdentityV1 {
  readonly version: 1;
  readonly packageId: string;
  readonly buildId: string;
  readonly protocolVersion: typeof HOST_PROTOCOL_VERSION_V1;
  readonly nodeVersion: string;
  readonly platform: string;
  readonly arch: string;
}

export interface HostArtifactManifestV1 {
  readonly version: 1;
  readonly manifestId: string;
  readonly build: ArtifactManifestBuildIdentityV1;
  readonly buildTimestamp: string;
  readonly outputRoot: string;
  readonly outputs: readonly ArtifactManifestEntryV1[];
}

// ─── Known entry point names ───────────────────────────────────────────────

export const ARTIFACT_ENTRY_HOST = 'host';
export const ARTIFACT_ENTRY_CONTRACTS = 'contracts';
export const ARTIFACT_ENTRY_MCP = 'mcp';
export const ARTIFACT_ENTRY_PERSISTENCE_WORKER = 'persistence-worker';

// ─── Build identity ────────────────────────────────────────────────────────

export function buildManifestIdentity(
  packageId: string,
  buildId: string | undefined,
): ArtifactManifestBuildIdentityV1 {
  const id =
    buildId !== undefined && /^[A-Za-z0-9._-]{1,128}$/.test(buildId)
      ? buildId
      : 'development';
  return {
    version: 1,
    packageId,
    buildId: id,
    protocolVersion: HOST_PROTOCOL_VERSION_V1,
    nodeVersion: process.versions.node,
    platform: platform(),
    arch: arch(),
  };
}

// ─── Entry hash computation ────────────────────────────────────────────────

function hashFile(filePath: string): string {
  const hash = createHash('sha256');
  hash.update(readFileSync(filePath));
  return hash.digest('hex');
}

function relativeArtifactPath(outputRoot: string, filePath: string): string {
  const root = resolve(outputRoot);
  const absolute = resolve(root, filePath);
  const rel = relative(root, absolute);
  if (
    rel.length === 0 ||
    isAbsolute(rel) ||
    rel === '..' ||
    rel.startsWith(`..${sep}`) ||
    rel.split(sep).some((part) => part === '')
  ) {
    throw new ArtifactManifestError(
      'MANIFEST_PATH_INVALID',
      `Artifact output path escapes output root: ${filePath}`,
    );
  }
  return rel.split(sep).join('/');
}

function artifactPath(outputRoot: string, entryPath: string): string {
  const root = resolve(outputRoot);
  const absolute = resolve(root, entryPath);
  const rel = relative(root, absolute);
  if (
    rel.length === 0 ||
    isAbsolute(rel) ||
    rel === '..' ||
    rel.startsWith(`..${sep}`)
  ) {
    throw new ArtifactManifestError(
      'MANIFEST_PATH_INVALID',
      `Artifact output path escapes output root: ${entryPath}`,
    );
  }
  return absolute;
}

export interface BuildManifestOptions {
  readonly outputRoot: string;
  readonly packageId: string;
  readonly buildId?: string;
  /** Map of entry point name → relative output path. */
  readonly entryPoints: Record<string, string>;
  /** All output files that should be tracked in the manifest. */
  readonly outputFiles: readonly string[];
}

export function buildArtifactManifest(
  options: BuildManifestOptions,
): HostArtifactManifestV1 {
  const outputRoot = resolve(options.outputRoot);
  const outputs: ArtifactManifestEntryV1[] = [];
  const entryByPath = new Map<string, string>();
  for (const [name, filePath] of Object.entries(options.entryPoints)) {
    if (!/^[A-Za-z0-9._-]{1,128}$/.test(name)) {
      throw new ArtifactManifestError('MANIFEST_ENTRY_INVALID', `Invalid artifact entry point: ${name}`);
    }
    entryByPath.set(relativeArtifactPath(outputRoot, filePath), name);
  }

  const seen = new Set<string>();
  for (const filePath of options.outputFiles) {
    const normalizedPath = relativeArtifactPath(outputRoot, filePath);
    if (seen.has(normalizedPath)) continue;
    seen.add(normalizedPath);
    const absPath = resolve(outputRoot, normalizedPath);
    const st = statSync(absPath, { throwIfNoEntry: false });
    if (st === undefined) continue; // source maps may be disabled by a build.
    if (!st.isFile()) {
      throw new ArtifactManifestError(
        'MANIFEST_OUTPUT_NOT_FILE',
        `Artifact output is not a file: ${normalizedPath}`,
      );
    }
    outputs.push({
      path: normalizedPath,
      hash: hashFile(absPath),
      size: st.size,
      entryPointFor: entryByPath.get(normalizedPath),
    });
  }

  return {
    version: 1,
    manifestId: randomUUID(),
    build: buildManifestIdentity(options.packageId, options.buildId),
    buildTimestamp: new Date().toISOString(),
    outputRoot,
    outputs,
  };
}

// ─── Manifest loading and validation (launch-time) ─────────────────────────

export class ArtifactManifestError extends Error {
  readonly code: string;
  constructor(code: string, message: string) {
    super(message);
    this.name = 'ArtifactManifestError';
    this.code = code;
  }
}

export function loadArtifactManifest(manifestPath: string): HostArtifactManifestV1 {
  let raw: unknown;
  try {
    raw = JSON.parse(readFileSync(manifestPath, 'utf8'));
  } catch (error) {
    throw new ArtifactManifestError(
      'MANIFEST_PARSE_FAILED',
      `Cannot parse artifact manifest at ${manifestPath}: ${(error as Error).message}`,
    );
  }
  return validateArtifactManifest(raw, manifestPath);
}

function validateArtifactManifest(
  value: unknown,
  source: string,
): HostArtifactManifestV1 {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      `Artifact manifest must be a JSON object: ${source}`,
    );
  }
  const obj = value as Record<string, unknown>;

  if (obj.version !== 1) {
    throw new ArtifactManifestError(
      'MANIFEST_VERSION_UNSUPPORTED',
      `Unsupported manifest version: ${obj.version}`,
    );
  }
  if (typeof obj.manifestId !== 'string' || obj.manifestId.length === 0) {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'manifestId must be a non-empty string',
    );
  }
  if (
    typeof obj.buildTimestamp !== 'string' ||
    Number.isNaN(Date.parse(obj.buildTimestamp))
  ) {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'buildTimestamp must be an ISO timestamp string',
    );
  }
  if (typeof obj.outputRoot !== 'string' || !isAbsolute(obj.outputRoot)) {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'outputRoot must be an absolute path string',
    );
  }

  const build = obj.build;
  if (typeof build !== 'object' || build === null) {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'build must be an object',
    );
  }
  const b = build as Record<string, unknown>;
  if (
    Object.keys(b).sort().join(',') !==
      'arch,buildId,nodeVersion,packageId,platform,protocolVersion,version'
  ) {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'build contains unknown or missing fields',
    );
  }
  if (b.version !== 1) {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'build.version must be 1',
    );
  }
  if (typeof b.packageId !== 'string' || b.packageId.length === 0) {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'build.packageId must be a non-empty string',
    );
  }
  if (typeof b.buildId !== 'string' || b.buildId.length === 0) {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'build.buildId must be a non-empty string',
    );
  }
  if (b.protocolVersion !== HOST_PROTOCOL_VERSION_V1) {
    throw new ArtifactManifestError(
      'MANIFEST_PROTOCOL_MISMATCH',
      `build.protocolVersion must be ${HOST_PROTOCOL_VERSION_V1}`,
    );
  }
  if (typeof b.nodeVersion !== 'string') {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'build.nodeVersion must be a string',
    );
  }
  if (typeof b.platform !== 'string') {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'build.platform must be a string',
    );
  }
  if (typeof b.arch !== 'string') {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'build.arch must be a string',
    );
  }

  if (!Array.isArray(obj.outputs)) {
    throw new ArtifactManifestError(
      'MANIFEST_INVALID',
      'outputs must be an array',
    );
  }
  const validatedOutputs: ArtifactManifestEntryV1[] = [];
  const outputPaths = new Set<string>();
  for (const entry of obj.outputs) {
    if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) {
      throw new ArtifactManifestError(
        'MANIFEST_INVALID',
        'each output entry must be an object',
      );
    }
    const e = entry as Record<string, unknown>;
    const keys = Object.keys(e).sort().join(',');
    if (keys !== 'hash,path,size' && keys !== 'entryPointFor,hash,path,size') {
      throw new ArtifactManifestError(
        'MANIFEST_INVALID',
        'output entries contain unknown or missing fields',
      );
    }
    if (typeof e.path !== 'string' || e.path.length === 0) {
      throw new ArtifactManifestError(
        'MANIFEST_INVALID',
        'each output entry must have a non-empty relative path string',
      );
    }
    const normalizedPath = relativeArtifactPath(obj.outputRoot as string, e.path);
    if (normalizedPath !== e.path || e.path.includes('\\')) {
      throw new ArtifactManifestError(
        'MANIFEST_PATH_INVALID',
        `output path is not canonical and relative: ${e.path}`,
      );
    }
    if (outputPaths.has(e.path)) {
      throw new ArtifactManifestError('MANIFEST_INVALID', `duplicate output path: ${e.path}`);
    }
    outputPaths.add(e.path);
    if (typeof e.hash !== 'string' || !/^[0-9a-f]{64}$/.test(e.hash)) {
      throw new ArtifactManifestError(
        'MANIFEST_INVALID',
        `output entry ${e.path} hash must be a 64-char hex string`,
      );
    }
    if (typeof e.size !== 'number' || !Number.isSafeInteger(e.size) || e.size < 0) {
      throw new ArtifactManifestError(
        'MANIFEST_INVALID',
        `output entry ${e.path} size must be a non-negative integer`,
      );
    }
    if (
      e.entryPointFor !== undefined &&
      (typeof e.entryPointFor !== 'string' || !/^[A-Za-z0-9._-]{1,128}$/.test(e.entryPointFor))
    ) {
      throw new ArtifactManifestError(
        'MANIFEST_INVALID',
        `output entry ${e.path} has an invalid entryPointFor`,
      );
    }
    artifactPath(obj.outputRoot as string, e.path);
    validatedOutputs.push({
      path: e.path,
      hash: e.hash,
      size: e.size,
      ...(e.entryPointFor === undefined ? {} : { entryPointFor: e.entryPointFor }),
    });
  }

  const validatedBuild: ArtifactManifestBuildIdentityV1 = {
    version: 1,
    packageId: b.packageId as string,
    buildId: b.buildId as string,
    protocolVersion: HOST_PROTOCOL_VERSION_V1,
    nodeVersion: b.nodeVersion as string,
    platform: b.platform as string,
    arch: b.arch as string,
  };

  return {
    version: 1,
    manifestId: obj.manifestId as string,
    build: validatedBuild,
    buildTimestamp: obj.buildTimestamp as string,
    outputRoot: obj.outputRoot as string,
    outputs: validatedOutputs,
  };
}

// ─── Entry lookup ──────────────────────────────────────────────────────────

export function findManifestEntry(
  manifest: HostArtifactManifestV1,
  entryPoint: string,
): ArtifactManifestEntryV1 | undefined {
  return manifest.outputs.find((e) => e.entryPointFor === entryPoint);
}

export function resolveManifestEntryPath(
  manifest: HostArtifactManifestV1,
  entryPoint: string,
): string | undefined {
  const entry = findManifestEntry(manifest, entryPoint);
  if (entry === undefined) return undefined;
  return artifactPath(manifest.outputRoot, entry.path);
}

/** Verify that every tracked output file still matches its recorded hash. */
export function verifyManifestIntegrity(
  manifest: HostArtifactManifestV1,
): { ok: true } | { ok: false; errors: string[] } {
  const errors: string[] = [];
  for (const entry of manifest.outputs) {
    try {
      const absPath = artifactPath(manifest.outputRoot, entry.path);
      const stat = statSync(absPath);
      const actualHash = createHash('sha256').update(readFileSync(absPath)).digest('hex');
      if (stat.size !== entry.size) {
        errors.push(
          `Size mismatch for ${entry.path}: expected ${entry.size}, got ${stat.size}`,
        );
      }
      if (actualHash !== entry.hash) {
        errors.push(
          `Hash mismatch for ${entry.path}: expected ${entry.hash}, got ${actualHash}`,
        );
      }
    } catch (error) {
      errors.push(`Cannot read ${entry.path}: ${(error as Error).message}`);
    }
  }
  return errors.length === 0 ? { ok: true } : { ok: false, errors };
}